    /// <summary>Dispatches to the <see cref="AstVisitor"/> method for the concrete node kind.</summary>
    public void Accept(AstVisitor visitor)
    {
        switch (Kind)
        {
            case NodeKind.Program: visitor.VisitProgram(new Program(_ast, _id)); break;
            case NodeKind.ArrayLiteral: visitor.VisitArrayLiteral(new ArrayLiteral(_ast, _id)); break;
            case NodeKind.ArrowFunctionLiteral: visitor.VisitArrowFunctionLiteral(new ArrowFunctionLiteral(_ast, _id)); break;
            case NodeKind.AssignExpression: visitor.VisitAssignExpression(new AssignExpression(_ast, _id)); break;
            case NodeKind.AwaitExpression: visitor.VisitAwaitExpression(new AwaitExpression(_ast, _id)); break;
            case NodeKind.BigIntLiteral: visitor.VisitBigIntLiteral(new BigIntLiteral(_ast, _id)); break;
            case NodeKind.BinaryExpression: visitor.VisitBinaryExpression(new BinaryExpression(_ast, _id)); break;
            case NodeKind.BooleanLiteral: visitor.VisitBooleanLiteral(new BooleanLiteral(_ast, _id)); break;
            case NodeKind.CallExpression: visitor.VisitCallExpression(new CallExpression(_ast, _id)); break;
            case NodeKind.ClassLiteral: visitor.VisitClassLiteral(new ClassLiteral(_ast, _id)); break;
            case NodeKind.ConditionalExpression: visitor.VisitConditionalExpression(new ConditionalExpression(_ast, _id)); break;
            case NodeKind.FunctionLiteral: visitor.VisitFunctionLiteral(new FunctionLiteral(_ast, _id)); break;
            case NodeKind.Identifier: visitor.VisitIdentifier(new Identifier(_ast, _id)); break;
            case NodeKind.InvalidExpression: visitor.VisitInvalidExpression(new InvalidExpression(_ast, _id)); break;
            case NodeKind.LogicalExpression: visitor.VisitLogicalExpression(new LogicalExpression(_ast, _id)); break;
            case NodeKind.MemberExpression: visitor.VisitMemberExpression(new MemberExpression(_ast, _id)); break;
            case NodeKind.MetaProperty: visitor.VisitMetaProperty(new MetaProperty(_ast, _id)); break;
            case NodeKind.NewExpression: visitor.VisitNewExpression(new NewExpression(_ast, _id)); break;
            case NodeKind.NullLiteral: visitor.VisitNullLiteral(new NullLiteral(_ast, _id)); break;
            case NodeKind.NumberLiteral: visitor.VisitNumberLiteral(new NumberLiteral(_ast, _id)); break;
            case NodeKind.ObjectLiteral: visitor.VisitObjectLiteral(new ObjectLiteral(_ast, _id)); break;
            case NodeKind.Optional: visitor.VisitOptional(new Optional(_ast, _id)); break;
            case NodeKind.OptionalChain: visitor.VisitOptionalChain(new OptionalChain(_ast, _id)); break;
            case NodeKind.PrivateDotExpression: visitor.VisitPrivateDotExpression(new PrivateDotExpression(_ast, _id)); break;
            case NodeKind.PrivateIdentifier: visitor.VisitPrivateIdentifier(new PrivateIdentifier(_ast, _id)); break;
            case NodeKind.RegExpLiteral: visitor.VisitRegExpLiteral(new RegExpLiteral(_ast, _id)); break;
            case NodeKind.SequenceExpression: visitor.VisitSequenceExpression(new SequenceExpression(_ast, _id)); break;
            case NodeKind.SpreadElement: visitor.VisitSpreadElement(new SpreadElement(_ast, _id)); break;
            case NodeKind.StringLiteral: visitor.VisitStringLiteral(new StringLiteral(_ast, _id)); break;
            case NodeKind.SuperExpression: visitor.VisitSuperExpression(new SuperExpression(_ast, _id)); break;
            case NodeKind.TemplateLiteral: visitor.VisitTemplateLiteral(new TemplateLiteral(_ast, _id)); break;
            case NodeKind.ThisExpression: visitor.VisitThisExpression(new ThisExpression(_ast, _id)); break;
            case NodeKind.UnaryExpression: visitor.VisitUnaryExpression(new UnaryExpression(_ast, _id)); break;
            case NodeKind.UpdateExpression: visitor.VisitUpdateExpression(new UpdateExpression(_ast, _id)); break;
            case NodeKind.YieldExpression: visitor.VisitYieldExpression(new YieldExpression(_ast, _id)); break;
            case NodeKind.TemplateElement: visitor.VisitTemplateElement(new TemplateElement(_ast, _id)); break;
            case NodeKind.BadStatement: visitor.VisitBadStatement(new BadStatement(_ast, _id)); break;
